nodes.css:
.wrap { position: absolute; inset: 0; display: flex; flex-direction: column;
  justify-content: center; align-items: flex-start; padding-left: 220px; gap: 24px; }
.kicker { font-family: JetBrains Mono, DejaVu Sans Mono, monospace; font-size: 17px; font-weight: 600;
  letter-spacing: 0.3em; color: #d9a441;
  animation: rise 0.5s cubic-bezier(0.16,1,0.3,1) 0.1s both; }
.num { font-family: Archivo, Inter, DejaVu Sans; font-size: 290px; font-weight: 800;
  letter-spacing: -0.045em; color: #f4f1ea; line-height: 0.9;
  animation: rise 0.6s cubic-bezier(0.16,1,0.3,1) 0.2s both; }
.rule { width: 0px; height: 5px; border-radius: 3px; background: #d9a441;
  animation: draw 0.85s cubic-bezier(0.16,1,0.3,1) 0.5s both; }
.title { font-family: Inter, DejaVu Sans; font-size: 40px; font-weight: 400;
  color: #9a978e; line-height: 1.2;
  animation: rise 0.5s cubic-bezier(0.16,1,0.3,1) 0.58s both; }
@keyframes rise { from { opacity: 0; transform: translateY(14px) } to { opacity: 1; transform: translateY(0) } }
@keyframes draw { from { width: 0px } to { width: 460px } }
